-- ============================================================
-- Migration v15 — Nutrition redesign
--
-- 1. foods: curated global library (user_id NULL) + per-user custom
--    and AI-estimated foods. Seeded at the bottom of this file from
--    lib/data/foods-seed.ts (regenerate with
--    `npx tsx scripts/foods-seed-to-sql.ts`).
-- 2. food_favorites: starred foods per user.
-- 3. weigh_ins: one weight per user per day. Private to the athlete —
--    deliberately NO coach/admin read policy.
-- 4. food_entries gains food_id / servings / serving_size. Macros stay
--    denormalized per entry so history never changes when a food is
--    edited. Existing rows read as servings = 1.
-- 5. nutrition_goals gains the calorie-quiz inputs. Body data lives
--    here, not in profiles, so update_user_profile() is untouched.
--
-- Idempotent — safe to re-run. Run BEFORE deploying the v15 app code.
-- ============================================================

-- 1. foods ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.foods (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       UUID REFERENCES public.profiles(id) ON DELETE CASCADE,
  slug          TEXT UNIQUE,
  name          TEXT NOT NULL,
  brand         TEXT,
  category      TEXT NOT NULL DEFAULT 'other' CHECK (category IN (
    'protein','carb','fruit_veg','dairy','snack','drink','fast_food','meal','supplement','other')),
  serving_size  TEXT NOT NULL,
  serving_grams NUMERIC(7,1),
  calories      INT NOT NULL CHECK (calories >= 0),
  protein_g     NUMERIC(6,1) NOT NULL DEFAULT 0,
  carbs_g       NUMERIC(6,1) NOT NULL DEFAULT 0,
  fat_g         NUMERIC(6,1) NOT NULL DEFAULT 0,
  source        TEXT NOT NULL DEFAULT 'curated' CHECK (source IN ('curated','user','ai')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_foods_user ON public.foods(user_id);
CREATE INDEX IF NOT EXISTS idx_foods_name_lower ON public.foods(lower(name));

ALTER TABLE public.foods ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Read global and own foods" ON public.foods;
CREATE POLICY "Read global and own foods" ON public.foods
  FOR SELECT TO authenticated
  USING (user_id IS NULL OR user_id = auth.uid());
DROP POLICY IF EXISTS "Users manage own foods" ON public.foods;
CREATE POLICY "Users manage own foods" ON public.foods
  FOR ALL TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

-- 2. food_favorites ------------------------------------------------
CREATE TABLE IF NOT EXISTS public.food_favorites (
  user_id    UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  food_id    UUID NOT NULL REFERENCES public.foods(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, food_id)
);
ALTER TABLE public.food_favorites ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own food_favorites" ON public.food_favorites;
CREATE POLICY "Users manage own food_favorites" ON public.food_favorites
  FOR ALL TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

-- 3. weigh_ins (athlete-private) ----------------------------------
CREATE TABLE IF NOT EXISTS public.weigh_ins (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  entry_date DATE NOT NULL DEFAULT CURRENT_DATE,
  weight_lb  NUMERIC(5,1) NOT NULL CHECK (weight_lb BETWEEN 50 AND 500),
  note       TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, entry_date)
);
CREATE INDEX IF NOT EXISTS idx_weigh_ins_user_date ON public.weigh_ins(user_id, entry_date DESC);
ALTER TABLE public.weigh_ins ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own weigh_ins" ON public.weigh_ins;
CREATE POLICY "Users manage own weigh_ins" ON public.weigh_ins
  FOR ALL TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

-- 4. food_entries additions ---------------------------------------
ALTER TABLE public.food_entries
  ADD COLUMN IF NOT EXISTS food_id      UUID REFERENCES public.foods(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS servings     NUMERIC(5,2) NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS serving_size TEXT;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'food_entries_servings_check') THEN
    ALTER TABLE public.food_entries
      ADD CONSTRAINT food_entries_servings_check CHECK (servings > 0 AND servings <= 50);
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS idx_food_entries_user_created ON public.food_entries(user_id, created_at DESC);

-- 5. nutrition_goals quiz inputs ----------------------------------
ALTER TABLE public.nutrition_goals
  ADD COLUMN IF NOT EXISTS goal_type         TEXT CHECK (goal_type IN ('gain','lose','maintain')),
  ADD COLUMN IF NOT EXISTS activity_level    TEXT CHECK (activity_level IN ('light','moderate','high')),
  ADD COLUMN IF NOT EXISTS current_weight_lb NUMERIC(5,1) CHECK (current_weight_lb BETWEEN 50 AND 500),
  ADD COLUMN IF NOT EXISTS target_weight_lb  NUMERIC(5,1) CHECK (target_weight_lb BETWEEN 50 AND 500),
  ADD COLUMN IF NOT EXISTS quiz_completed_at TIMESTAMPTZ;

NOTIFY pgrst, 'reload schema';

-- 6. Curated seed — GENERATED, do not hand-edit -------------------
-- (appended by `npx tsx scripts/foods-seed-to-sql.ts >> supabase-migration-v15-nutrition.sql`)
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, brand=EXCLUDED.brand, category=EXCLUDED.category, serving_size=EXCLUDED.serving_size, serving_grams=EXCLUDED.serving_grams, calories=EXCLUDED.calories, protein_g=EXCLUDED.protein_g, carbs_g=EXCLUDED.carbs_g, fat_g=EXCLUDED.fat_g;
